from pathlib import Path
from datetime import datetime, timezone
from zoneinfo import ZoneInfo
from hashlib import sha256
import re, json, sys
root=Path('$USER_HOME/Desktop/lenny')
started=datetime.now(timezone.utc).isoformat()
checks=[]
def check(name,condition,detail): checks.append({'check':name,'passed':bool(condition),'detail':detail})
required=['AGENTS.md','.gitignore','README.md','LENNY_BUILD_FLOW.md','LENNY_CODEX_PROMPTS.md']+['docs/'+n+'.md' for n in ['PRD','assumptions','risks','scenarios','requirements','decisions','assessment-audit','environment','provenance','progress']]+['docs/agent-transcripts/'+n for n in ['README.md','phase-00-summary.md','phase-00-earlier-environment.json','phase-00-environment.jsonl','phase-00-source-audit.json','phase-00-assignment-source.json']]
check('Required baseline files',all((root/p).is_file() for p in required),{'count':len(required),'missing':[p for p in required if not (root/p).is_file()]})
plan=(root/'LENNY_BUILD_FLOW.md').read_text()
req=(root/'docs/requirements.md').read_text()
id_pattern=r'^\| ((?:FD|API|AG|SES|DB|MOD|KB|RAG|ESS|ART|OPS|DEL)-\d+) \|'
expected=re.findall(id_pattern,plan,re.M)
actual=re.findall(id_pattern,req,re.M)
check('All requirement IDs exactly once',set(expected)==set(actual) and len(actual)==len(set(actual))==29,{'expected':len(expected),'actual':len(actual),'missing':sorted(set(expected)-set(actual)),'extra':sorted(set(actual)-set(expected))})
deliverables=[f'DEL-{i:02}' for i in range(1,9)]
check('All eight deliverables',all(x in actual for x in deliverables),deliverables)
statuses=[]
for line in req.splitlines():
 if re.match(id_pattern,line): statuses.append(line.split('|')[-3].strip())
check('Honest requirement statuses',set(statuses)<=set(['pending','implemented','verified','blocked']) and 'verified' not in statuses,{'counts':{s:statuses.count(s) for s in sorted(set(statuses))}})
prd=(root/'docs/PRD.md').read_text()
brief=prd.split('## Authority')[0]
check('Opening five-part discovery brief',all(s in brief for s in ['User, job and pain','Measurable success','Assumptions','Reasoned scope','Risks and trade-offs','not been confirmed by client interviews']),{'manual_review':'Five concrete elements, no claimed client interview; proposed versus actual metrics separated.'})
scenarios=(root/'docs/scenarios.md').read_text()
check('Five predefined journeys',all('SC-01-'+x in scenarios for x in 'ABCDE') and 'before retrieval/generation tuning' in scenarios,{'manual_review':'Exact questions/evidence/caps intentionally unfrozen pending actual source/hardware inspection; no scenario outcome claimed.'})
links=[]
for p in root.rglob('*.md'):
 for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)',p.read_text()):
  if target.startswith(('https://','http://','#','mailto:')): continue
  local=target.split('#',1)[0]
  if local and not (p.parent/local).exists(): links.append({'file':str(p.relative_to(root)),'target':target})
check('Markdown local links resolve',not links,links)
files=[p for p in root.rglob('*') if p.is_file() and p.name != '.DS_Store']
# Finder metadata is ignored by .gitignore; inspect all other files, including unexpected binary/code files.
unexpected=[str(p.relative_to(root)) for p in files if p.suffix not in ['.md','.json','.jsonl'] and p.name!='.gitignore']
check('Documentation precedes implementation; no confidential PDF/corpus/code',not unexpected,{'unexpected_files':unexpected,'prd_birthtime':datetime.fromtimestamp((root/'docs/PRD.md').stat().st_birthtime,ZoneInfo('Asia/Kolkata')).isoformat(),'application_code_files':0})
for destination,source in [('LENNY_BUILD_FLOW.md','LENNY_BUILD_FLOW (1).md'),('LENNY_CODEX_PROMPTS.md','LENNY_CODEX_PROMPTS.md')]:
 check('Unchanged source copy '+destination,(root/destination).read_bytes()==(Path('$USER_HOME/Desktop')/source).read_bytes(),{'sha256':sha256((root/destination).read_bytes()).hexdigest()})
json_errors=[]
for p in files:
 if p.suffix=='.json':
  try: json.loads(p.read_text())
  except Exception as e: json_errors.append({'path':str(p.relative_to(root)),'error':str(e)})
 elif p.suffix=='.jsonl':
  try:
   for line in p.read_text().splitlines(): json.loads(line)
  except Exception as e: json_errors.append({'path':str(p.relative_to(root)),'error':str(e)})
check('Saved actual logs parse',not json_errors,json_errors)
suspects=[]
patterns=[r'\bsk-(?:ant-)?[A-Za-z0-9_-]{20,}',r'\bAKIA[A-Z0-9]{16}\b',r'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----']
for p in files:
 for pattern in patterns:
  if re.search(pattern,p.read_text()): suspects.append(str(p.relative_to(root)))
check('Bounded known-secret pattern check',not suspects,{'suspect_paths':suspects,'limit':'Pattern check plus manual review, not a complete credential/security audit; no Git history exists.'})
passed=all(c['passed'] for c in checks)
if passed:
 p=root/'docs/progress.md'
 text=p.read_text().replace('Prompt 00 discovery work complete; final documentation checks pending. Phase 0 exit gate: **AWAITING FINAL CHECKS**.','Prompt 00 complete. Phase 0 exit gate: **PASSED (documentation/discovery only)**.').replace('| Final documentation audit | Pending; result will be saved in agent-transcripts/phase-00-checks.jsonl. |','| Final documentation audit | Passed: baseline files, all 29 IDs once, eight deliverables, honest statuses, five-part opening brief, five journeys, local links, source hashes, valid saved logs, no app/PDF/corpus and bounded known-secret scan. Evidence: agent-transcripts/phase-00-checks.jsonl. |')
 p.write_text(text)
record={'kind':'actual_documentation_audit','started_at':started,'ended_at':datetime.now(timezone.utc).isoformat(),'command':['python3','/private/tmp/lenny-phase00-checks.py'],'script_source':Path(__file__).read_text(),'revision':'no Git repository; see phase-00-manifest.json for file hashes','checks':checks,'exit_code':0 if passed else 1,'product_tests_run':False,'manual_review':'Assessment Sections 2-8 mapped independently; operational bullets and all deliverables present; assumptions/risk mitigations and proposed targets not claimed as measured; transcript/export gap disclosed.'}
log=root/'docs/agent-transcripts/phase-00-checks.jsonl'
with log.open('a') as f: f.write(json.dumps(record)+'\n')
manifest={'created_at':datetime.now(timezone.utc).isoformat(),'note':'File identity for Phase 0; excludes this self-referential manifest. Birth times are observed filesystem metadata, not agent transcripts.','files':[{ 'path':str(p.relative_to(root)),'sha256':sha256(p.read_bytes()).hexdigest(),'created_at_india':datetime.fromtimestamp(p.stat().st_birthtime,ZoneInfo('Asia/Kolkata')).isoformat()} for p in sorted(root.rglob('*')) if p.is_file() and p.name not in ['phase-00-manifest.json','.DS_Store']]}
(root/'docs/agent-transcripts/phase-00-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
for c in checks: print(('PASS' if c['passed'] else 'FAIL')+' '+c['check']+': '+json.dumps(c['detail']))
print('Phase 0 documentation gate:', 'PASSED' if passed else 'FAILED')
print('No app/integration/browser/model tests run.')
sys.exit(0 if passed else 1)
